s($,"cuX","a3q",()=>{var q,p,o,n,m,l,k,j,i,h,g,f,e,d=63.66197723675813*A.Ar(50)/100,c=A.bQz(0.1,50),b=A.bNe(0.59,0.69,0.9999999999999998),a=1-0.2777777777777778*A.co0((-d-42)/92)
if(a>1)a=1
else if(a<0)a=0
q=A.b([a*1.0250597119338924+1-a,a*0.9837978481337839+1-a,a*0.9218550445387449+1-a],t.n)
p=5*d
o=1/(p+1)
n=o*o*o*o
m=1-n
l=n*d+0.1*m*m*A.a3b(p,0.3333333333333333)
k=A.Ar(c)/100
p=A.cqq(k)
j=0.725/A.a3b(k,0.2)
i=[A.a3b(l*q[0]*97.555292473/100,0.42),A.a3b(l*q[1]*101.64689848600003/100,0.42),A.a3b(l*q[2]*108.47692442799999/100,0.42)]
h=i[0]
g=i[1]
f=i[2]
e=[400*h/(h+27.13),400*g/(g+27.13),400*f/(f+27.13)]
return new A.b31(k,(40*e[0]+20*e[1]+e[2])/20*j,j,j,b,1,q,l,A.a3b(l,0.25),1.48+p)})
